// return trong finally nuốt mất exception
int bad() {
    try { throw new IllegalStateException("lỗi thật"); }
    finally { return 42; }   // trả về 42, exception biến mất không dấu vết
}

// Primitive: gán lại trong finally không ảnh hưởng giá trị đã trả
int tricky() {
    int x = 1;
    try { return x; }        // giá trị 1 đã được lưu
    finally { x = 99; }      // vẫn trả về 1
}

public class InsufficientBalanceException extends RuntimeException {
    private final String accountId;
    private final BigDecimal shortfall;

    public InsufficientBalanceException(String accountId, BigDecimal shortfall, Throwable cause) {
        super("Tài khoản %s thiếu %s".formatted(accountId, shortfall), cause);
        this.accountId = accountId;
        this.shortfall = shortfall;
    }

    public String accountId() { return accountId; }
    public BigDecimal shortfall() { return shortfall; }   // handler dùng được để dựng response
}

// Helper bọc checked exception
@FunctionalInterface interface ThrowingFunction<T, R> { R apply(T t) throws Exception; }

static <T, R> Function<T, R> unchecked(ThrowingFunction<T, R> f) {
    return t -> {
        try { return f.apply(t); }
        catch (Exception e) { throw new IllegalStateException("Lỗi khi xử lý " + t, e); }
    };
}

